"""Public, read-only dashboard. Never exposes secrets or enables trading."""
import html
import os
from datetime import datetime, timezone
from fastapi.responses import HTMLResponse

def dashboard(state=None):
    broker_state = state or {}
    def safe(v):
        return html.escape(str(v if v is not None else "Unavailable"))

    cards = []
    for label, name, icon in (("GOLD","Gold / XAUUSD","◈"),("OIL","Crude Oil","◉"),("US500","US 500","▥")):
        configured = bool(os.getenv("CAPITAL_" + label + "_EPIC", "").strip())
        state = "EPIC configured · unverified" if configured else "Not configured"
        detail = broker_state.get("markets", {}).get(label)
        tag = "pending" if configured else "muted"
        status = "PENDING" if configured else "NOT CONFIGURED"
        broker = "Not verified"
        extra = ""
        if detail:
            verified = detail.get("epic_matches") is True
            tag = "good" if verified else "pending"
            status = "VERIFIED" if verified else "UNVERIFIED"
            broker = "Verified" if verified else "Unverified"
            state_text = "Broker EPIC verified" if verified else detail.get("reason", "Broker EPIC not verified")
            extra = ('<div class="kv"><span>Market status</span><strong>' + safe(detail.get("market_status")) + '</strong></div>'
                     + '<div class="kv"><span>Bid / Offer</span><strong>' + safe(detail.get("bid")) + ' / ' + safe(detail.get("offer")) + '</strong></div>'
                     + '<div class="kv"><span>Contract size</span><strong>' + safe(detail.get("contract_size")) + '</strong></div>'
                     + '<div class="kv"><span>Margin factor</span><strong>' + safe(detail.get("margin_factor")) + '</strong></div>')
        else:
            state_text = "EPIC configured · unverified" if configured else "Not configured"
        cards.append(f"""<article class="market"><div class="market-top"><div class="symbol-icon">{icon}</div><span class="pill {tag}">{status}</span></div><h3>{name}</h3><p class="ticker">{label}</p><div class="rule"></div><div class="kv"><span>Broker verification</span><strong>{broker}</strong></div>{extra}<div class="kv"><span>Contract &amp; sizing</span><strong>Pending</strong></div><div class="kv"><span>Order execution</span><strong class="red">Disabled</strong></div><div class="market-foot">{safe(state_text)}</div></article>""")
    markets = "".join(cards)
    page = """<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="dark"><title>UT Bot | Command Centre</title><style>
:root{color-scheme:dark;--bg:#080e19;--panel:#101a2b;--border:#24324a;--text:#e9effa;--muted:#92a3bd;--teal:#49dfbc;--red:#ff8597;--amber:#ffca78}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 82% 2%,#183450 0%,transparent 42%),var(--bg);font:15px/1.55 system-ui,-apple-system,Segoe UI,sans-serif;color:var(--text)}.layout{max-width:1300px;margin:auto;padding:34px 30px 70px}.top{display:flex;justify-content:space-between;align-items:center;gap:18px;margin-bottom:55px}.brand{display:flex;align-items:center;gap:13px;font-size:18px;font-weight:750;letter-spacing:-.5px}.logo{width:42px;height:42px;display:grid;place-items:center;background:linear-gradient(135deg,#38c6af,#2e719f);border-radius:13px;color:#041724;font-size:24px;font-weight:900}.top-right{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.top-right a{color:#c7d7ef;text-decoration:none;font-size:13px;border:1px solid var(--border);padding:9px 13px;border-radius:10px}.pill{font-size:10px;letter-spacing:1.3px;font-weight:800;border:1px solid #3e5368;border-radius:100px;padding:6px 10px;color:#b3c2d6}.pill.good{color:var(--teal);background:#10352f;border-color:#205f52}.pill.bad{color:var(--red);background:#371e2c;border-color:#693746}.pill.pending{color:var(--amber);background:#3c2e1e;border-color:#65502e}.pill.muted{color:#a3b3c9;background:#1d293a}.eyebrow{color:var(--teal);font-size:12px;letter-spacing:2.4px;font-weight:800;text-transform:uppercase}h1{font-size:clamp(32px,5vw,56px);letter-spacing:-2.4px;line-height:1.1;margin:14px 0}h2{font-size:23px;letter-spacing:-.6px;margin:0}p{color:var(--muted)}.hero{display:flex;justify-content:space-between;align-items:end;gap:30px;margin-bottom:32px}.hero p{max-width:610px;margin-bottom:0}.hero-status{border:1px solid #31534f;background:#122c2c;padding:14px 18px;border-radius:12px;white-space:nowrap;color:#8af3d5;font-weight:650}.dot{display:inline-block;width:9px;height:9px;background:var(--teal);border-radius:50%;margin-right:8px;box-shadow:0 0 15px #39d8b6}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.tile,.market,.notice{border:1px solid var(--border);background:linear-gradient(145deg,#152136,#0e1727);border-radius:17px}.tile{padding:24px}.tile-label{color:var(--muted);font-size:12px;letter-spacing:.6px}.tile-value{font-size:27px;font-weight:780;margin:14px 0 7px;letter-spacing:-.9px}.tile-note{color:#8d9fb9;font-size:12px}.green{color:var(--teal)}.red{color:var(--red)}.amber{color:var(--amber)}.section-head{display:flex;justify-content:space-between;align-items:end;margin:44px 0 18px;gap:12px}.section-head p{margin:4px 0 0;font-size:13px}.markets{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.market{padding:25px}.market-top{display:flex;align-items:center;justify-content:space-between}.symbol-icon{width:46px;height:46px;display:grid;place-items:center;border-radius:12px;background:#1c3544;color:#7cebd5;font-size:24px}.market h3{font-size:22px;margin:24px 0 0}.ticker{font-size:12px;letter-spacing:1.5px;margin:2px 0 22px}.rule{height:1px;background:var(--border);margin-bottom:18px}.kv{display:flex;justify-content:space-between;gap:10px;margin:12px 0;font-size:13px}.kv span{color:var(--muted)}.kv strong{font-weight:600;text-align:right}.market-foot{margin-top:22px;padding:12px;background:#19263a;border-radius:9px;color:#afbed2;font-size:12px}.bottom{display:grid;grid-template-columns:1.3fr 1fr;gap:16px;margin-top:22px}.notice{padding:25px}.notice h3{margin:0 0 8px;font-size:16px}.notice p{font-size:13px;margin:0}.notice ul{color:#b8c7dc;font-size:13px;padding-left:19px;margin-bottom:0}.notice li{margin:7px 0}.footer{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;border-top:1px solid var(--border);padding-top:24px;margin-top:40px;color:#7186a3;font-size:12px}a{color:#80e8d3}@media(max-width:900px){.grid{grid-template-columns:repeat(2,1fr)}.markets{grid-template-columns:1fr}.bottom{grid-template-columns:1fr}.hero{display:block}.hero-status{display:inline-block;margin-top:20px}}@media(max-width:530px){.layout{padding:22px 16px 48px}.grid{grid-template-columns:1fr 1fr;gap:10px}.tile{padding:16px}.tile-value{font-size:21px}.top{margin-bottom:35px}.top-right{justify-content:flex-end}.top-right a{display:none}}
</style></head><body><main class="layout"><header class="top"><div class="brand"><div class="logo">↗</div><span>UT BOT <span style="color:#7e94b1;font-weight:450">/ COMMAND CENTRE</span></span></div><div class="top-right"><span class="pill good"><span class="dot"></span>SERVER ONLINE</span><span class="pill">DEMO ENVIRONMENT</span><a href="/docs">API docs ↗</a></div></header><section class="hero"><div><div class="eyebrow">Operations overview / Read-only</div><h1>Trading intelligence.<br><span style="color:#7d96b3">Execution on hold.</span></h1><p>Monitor your UT Bot infrastructure and market readiness. Broker connectivity, contract specifications and position sizing must be verified separately before any execution can be considered.</p></div><div class="hero-status">● SAFETY LOCK ACTIVE</div></section><section class="grid"><div class="tile"><div class="tile-label">APPLICATION</div><div class="tile-value green">Online</div><div class="tile-note">Web server operational</div></div><div class="tile"><div class="tile-label">TRADING ENGINE</div><div class="tile-value red">Disabled</div><div class="tile-note">No orders can be submitted</div></div><div class="tile"><div class="tile-label">MARKETS TRACKED</div><div class="tile-value">03</div><div class="tile-note">Gold · Oil · US500</div></div><div class="tile"><div class="tile-label">MARGIN TARGET</div><div class="tile-value">£1,500</div><div class="tile-note">Planning only · not verified</div></div></section><div class="section-head"><div><h2>Market validation</h2><p>Configuration visibility only — not live market quotes or broker approval.</p></div><span class="pill pending">VALIDATION PENDING</span></div><section class="markets">""" + markets + """</section><section class="bottom"><div class="notice"><h3>◈ Safety and execution controls</h3><p>This environment is deliberately fail-closed. No Capital.com order credentials are required for the dashboard. Readiness is not established by a successful deployment.</p><ul><li>Order submission and close-and-reverse execution are unavailable</li><li>Broker-confirmed contract size, GBP conversion and minimum increments remain pending</li><li>Prior one-off test locks and trading journal are not imported from the old service</li></ul></div><div class="notice"><h3>System information</h3><div class="kv"><span>Account mode</span><strong>DEMO only</strong></div><div class="kv"><span>Broker verification</span><strong class="amber">Not checked</strong></div><div class="kv"><span>Signal journal</span><strong>Local instance only</strong></div><div class="kv"><span>Risk engine</span><strong class="red">Not armed</strong></div><div class="kv"><span>API health</span><strong><a href="/health">View /health ↗</a></strong></div><p style="margin-top:15px">No live broker data is displayed on this page.</p></div></section><footer class="footer"><span>UT BOT / CAPITAL.COM DEMO · READ-ONLY CONTROL PANEL</span><span>Safety first · No automated execution</span></footer></main></body></html>"""
    page = page.replace("Not checked</strong>", safe(broker_state.get("connection", "Not checked")) + "</strong>")
    page = page.replace("No live broker data is displayed on this page.", "Broker market data shown only on this protected view." if broker_state else "No live broker data is displayed on this page.")
    reasons = {
        "unique_gbp_cfd_account_not_identified": "No unique GBP CFD demo account identified",
        "session_active_account_missing": "Capital.com session did not provide an active account ID",
        "active_session_account_mismatch": "Active session account differs from GBP CFD demo account",
        "verification_incomplete": "Account verification incomplete",
    }
    reason = broker_state.get("account_reason")
    if reason:
        detail = reasons.get(reason, "Account verification incomplete")
        count = broker_state.get("account_count")
        if count is not None:
            detail += " (matching accounts: " + safe(count) + ")"
        page = page.replace("Broker market data shown only on this protected view.", "Account check: " + safe(detail) + ". Broker market data shown only on this protected view.")
    return HTMLResponse(page, headers={"Cache-Control": "no-store"})

